SELECT CASE WHEN ss.revenue >= 3900 THEN 'high' WHEN ss.revenue >= 1100 THEN 'mid' ELSE 'low' END AS revenue_bucket, SUM(i.quantity) AS total_quantity, MAX(i.last_restock) AS latest_last_restock FROM inventory i INNER JOIN store_sales ss ON i.store_id = ss.store_id AND i.product_id = ss.product_id WHERE ss.revenue <= 2200 GROUP BY CASE WHEN ss.revenue >= 3900 THEN 'high' WHEN ss.revenue >= 1100 THEN 'mid' ELSE 'low' END ORDER BY total_quantity DESC
